<script setup lang="ts">import{onMounted,reactive}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';const form=reactive<any>({name:''});onMounted(async()=>Object.assign(form,(await api.get('/profile')).data));async function save(){await api.put('/profile',form);ElMessage.success('个人档案已保存')}</script><template><div class="panel profile"><div class="profile-head"><el-avatar :size="76">{{form.name?.slice(0,1)||'教'}}</el-avatar><div><h2>{{form.name||'教师姓名'}}</h2><p>{{form.college||'请完善学院信息'}} · {{form.current_title||'请完善当前职称'}}</p></div></div><el-form :model="form" label-width="110px"><div class="grid-2"><el-form-item label="姓名"><el-input v-model="form.name"/></el-form-item><el-form-item label="工号"><el-input v-model="form.employee_no"/></el-form-item><el-form-item label="学院"><el-input v-model="form.college"/></el-form-item><el-form-item label="专业"><el-input v-model="form.major"/></el-form-item><el-form-item label="当前职称"><el-input v-model="form.current_title"/></el-form-item><el-form-item label="学历 / 学位"><div style="display:flex;gap:8px"><el-input v-model="form.education"/><el-input v-model="form.degree"/></div></el-form-item><el-form-item label="参加工作时间"><el-date-picker v-model="form.work_start_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="现职称取得时间"><el-date-picker v-model="form.title_awarded_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.phone"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item></div><el-form-item label="个人简介"><el-input v-model="form.bio" type="textarea" :rows="5"/></el-form-item><el-form-item><el-button type="primary" @click="save">保存个人档案</el-button></el-form-item></el-form></div></template>